UPDATE tasks
SET status = #{status}, version = version + 1
WHERE id = #{taskId} AND space_id = #{spaceId} AND event_id = #{eventId}

UPDATE tasks
SET status = #{doneStatus}, version = version + 1,
    completed_by_user_id = #{completedByUserId}, completed_at = #{completedAt}
WHERE id = #{taskId} AND space_id = #{spaceId} AND event_id = #{eventId}
  AND version = #{version}
  AND status IN

    #{status}

UPDATE tasks
SET status = #{doingStatus}, version = version + 1,
    completed_by_user_id = NULL, completed_at = NULL
WHERE id = #{taskId} AND space_id = #{spaceId} AND event_id = #{eventId}
  AND version = #{version} AND status = #{doneStatus}
